		public void TestGetTextTrimmedBox31ForNormalLine()
		{
			CombineAssertions(() =>
			{
				AssertEquals("Box31 not trimmed when max length is more than text", "123456", SeparateBoxesHelper.GetTextTrimmedBox31ForNormalLine("123456", 20));
				AssertEquals("Box31 trimmed when one space", "1234567", SeparateBoxesHelper.GetTextTrimmedBox31ForNormalLine("1234567 7814", 10));
				AssertEquals("Box31 trimmed when more than one space but max length is on firts space", "1234567", SeparateBoxesHelper.GetTextTrimmedBox31ForNormalLine("1234567 7814 15", 10));
				AssertEquals("Box31 trimmed when more than one space", "1234567 78 14", SeparateBoxesHelper.GetTextTrimmedBox31ForNormalLine("1234567 78 14 15", 15));
				AssertEquals("Box31 trimmed when more than one space but max length is on first word", "123456", SeparateBoxesHelper.GetTextTrimmedBox31ForNormalLine("1234567 7814 15", 6));
			});
		}

		public void TestGetTextTrimmedBox44ForNormalLine()
		{
			CombineAssertions(() =>
			{
				AssertEquals("Box44 not trimmed when max length is more than text", "12345", SeparateBoxesHelper.GetTextTrimmedBox44ForNormalLine("12345", 20));
				AssertEquals("Box44 trimmed when one space", "12345;", SeparateBoxesHelper.GetTextTrimmedBox44ForNormalLine("12345; 12345", 6));
				AssertEquals("Box44 trimmed when more than one space but max length is on firts space", "12345", SeparateBoxesHelper.GetTextTrimmedBox44ForNormalLine("12345; 12345; 12345", 10));
				AssertEquals("Box44 trimmed when more than one space", "12345; 123; 45", SeparateBoxesHelper.GetTextTrimmedBox44ForNormalLine("12345; 123; 45; 12345", 19));
				AssertEquals("Box44 trimmed when more than one space but max length is on first word", "123", SeparateBoxesHelper.GetTextTrimmedBox44ForNormalLine("12345; 12345; 12345;", 3));
			});
		}

